using Westworld.Runtime.Core;
using System.Text.Json;
int checks=0;
void Check(bool value,string name){checks++;if(!value)throw new Exception(name);}
void Reject(Action action,string name){bool failed=false;try{action();}catch(ArgumentException){failed=true;}catch(InvalidOperationException){failed=true;}catch(FormatException){failed=true;}catch(JsonException){failed=true;}Check(failed,name);}
var fixture47Radii=new InterestRadii(16,24);fixture47Radii.Validate();
Check(fixture47Radii.FullReady>=Math.Sqrt(8*8+3*3),"scale47 legal fixture interest covers edit/readiness extent");
Reject(()=>new InterestRadii(12,20).Validate(),"scale47 prior below-minimum fixture rejected before native setup");
var world=Guid.NewGuid();var r=new ActorRegistry(world);var ids=Enumerable.Range(0,5).Select(_=>Guid.NewGuid()).ToArray();
foreach(var (id,i) in ids.Select((id,i)=>(id,i)))r.Add(id,"native-"+i,new(i*100,65,-i*100));
Check(r.Capture().Actors.Length==5,"five identity records, not five game bodies");
Check(r.RenderViews().Length==0,"actors do not allocate views");
Check(r.SimulationInterests().Length==5,"zero-view simulation interests");
string baseline=r.Serialize();var view=Guid.NewGuid();r.SetView(view,new(999,80,999));
Check(r.RenderViews().Length==1,"optional human view");Check(r.Serialize()==baseline,"view does not change actor checkpoint");
r.SetView(view,new(-500,100,400));Check(r.SimulationInterests().Length==5,"camera movement preserves interests");
Reject(()=>r.SetView(Guid.NewGuid(),default),"second human view outside current scope");
r.RemoveView(view);Check(r.RenderViews().Length==0&&r.SimulationInterests().Length==5,"removing last view preserves simulation");
var a=r.Read(ids[0]);r.Update(r.SessionId,a.Id,a.Revision,new(1000,66,1000),true);
Check(r.Read(a.Id).Revision==1,"native observation increments revision");Check(r.SimulationInterests().Single(x=>x.ActorId==a.Id).Center.X==1000,"interest follows actor not camera");
Reject(()=>r.Update(r.SessionId,a.Id,0,default,true),"stale revision rejected");
Reject(()=>r.Update(Guid.NewGuid(),a.Id,1,default,true),"wrong session rejected");
Reject(()=>r.Update(r.SessionId,a.Id,1,new(double.NaN,0,0),true),"nonfinite position rejected");
Check(r.Read(a.Id).Revision==1,"rejections leave state unchanged");
r.Update(r.SessionId,ids[1],0,new(100,65,-100),false);Check(r.SimulationInterests().Length==4,"inactive actor has no active interest");
Check(r.Capture().Actors.Length==5,"inactive actor remains persistent");
string saved=r.Serialize();var restored=ActorRegistry.Restore(saved,world);
Check(restored.Serialize()==saved,"actor identity pose revision activity round trip");
Check(restored.SessionId!=r.SessionId,"restore creates new runtime session");
Check(restored.RenderViews().Length==0,"views never restored implicitly");
Check(restored.SimulationInterests().Length==0,"restore waits for native entity reconciliation");
Reject(()=>restored.Update(restored.SessionId,ids[0],1,default,true),"unreconciled actor cannot update");
Reject(()=>restored.Rebind(restored.SessionId,ids[0],"wrong-native-key",default),"wrong native body cannot rebind");
foreach(var savedActor in restored.Capture().Actors)restored.Rebind(restored.SessionId,savedActor.Id,savedActor.EntityKey,savedActor.Position);
Check(restored.SimulationInterests().Length==4,"reconciled active interests restored");
Reject(()=>restored.Rebind(restored.SessionId,ids[0],"native-0",default),"duplicate native rebind rejected");
Reject(()=>restored.Update(r.SessionId,ids[0],1,default,true),"pre-restart command rejected");
Reject(()=>ActorRegistry.Restore(saved,Guid.NewGuid()),"wrong world rejected");
Reject(()=>ActorRegistry.Restore(saved.Replace("\"Schema\":1","\"Schema\":2"),world),"unknown schema rejected");
Reject(()=>ActorRegistry.Restore(saved.Replace("\"Schema\":1","\"Schema\":1,\"Schema\":1"),world),"duplicate json rejected");
Reject(()=>ActorRegistry.Restore(saved.Replace("\"Schema\":1","\"Extra\":0,\"Schema\":1"),world),"unknown field rejected");
Reject(()=>ActorRegistry.Restore(saved.Replace("\"Active\":true", "\"ActiveRenamed\":true"),world),"renamed required actor field rejected");
Reject(()=>ActorRegistry.Restore(saved.Replace(",\"Active\":true", ""),world),"missing active field rejected instead of default false");
Reject(()=>ActorRegistry.Restore(saved.Replace("\"Revision\":1", "\"Revision\":-1"),world),"negative revision rejected");
Reject(()=>ActorRegistry.Restore(saved.Replace("\"X\":1000,", ""),world),"missing coordinate rejected instead of zero");
var snap=r.Capture();snap.Actors[0]=snap.Actors[1];Reject(()=>ActorRegistry.Restore(JsonSerializer.Serialize(snap),world),"duplicate saved actor rejected");
Check(r.Serialize()==saved,"mutating snapshot copy cannot mutate live registry");
Reject(()=>r.Add(ids[0],"new",default),"duplicate actor rejected");Reject(()=>r.Add(Guid.NewGuid(),"native-0",default),"duplicate native binding rejected");
Reject(()=>r.Add(Guid.NewGuid(),"",default),"empty binding rejected");Reject(()=>r.Add(Guid.NewGuid(),"unsafe\nkey",default),"control character binding rejected");
Reject(()=>r.Add(Guid.NewGuid(),"large",new(1e20,0,0)),"position envelope rejected");
Reject(()=>new ActorRegistry(Guid.Empty),"empty world rejected");
bool crossThread=Task.Run(()=>{try{r.Capture();return false;}catch(InvalidOperationException){return true;}}).GetAwaiter().GetResult();
Check(crossThread,"cross-thread state access rejected");
r.Remove(ids[2]);Check(r.Capture().Actors.Length==4&&r.SimulationInterests().Length==3,"remove clears identity and active interest");
Check(ActorRegistry.Restore(r.Serialize(),world).Capture().Actors.Length==4,"removed identity does not reappear");
Reject(()=>r.Add(ids[2],"replacement",default),"removed id cannot be reused in same session");
var afterRemoval=ActorRegistry.Restore(r.Serialize(),world);
Reject(()=>afterRemoval.Add(ids[2],"replacement",default),"retired id persists across restart");
var invalidRetirement=r.Capture() with {RetiredIds=new[]{ids[0]}};
Reject(()=>ActorRegistry.Restore(JsonSerializer.Serialize(invalidRetirement),world),"live actor cannot also be retired");
invalidRetirement=r.Capture() with {RetiredIds=new[]{ids[2],ids[2]}};
Reject(()=>ActorRegistry.Restore(JsonSerializer.Serialize(invalidRetirement),world),"duplicate retired identity rejected");
Check(afterRemoval.Capture().RetiredIds.Contains(ids[2]),"tombstone retained in checkpoint");
var interestsRegistry=new ActorRegistry(Guid.NewGuid());var backend=new RecordingBackend();
var interestIds=Enumerable.Range(0,5).Select(_=>Guid.NewGuid()).ToArray();
foreach(var (id,i) in interestIds.Select((id,i)=>(id,i)))interestsRegistry.Add(id,"body-"+i,new(i*100,65,0));
var coordinator=new InterestCoordinator(interestsRegistry,backend,new(32,64));coordinator.Sync();
Check(backend.Published==1,"complete batch explicitly published");
Check(backend.Centers.Count==5,"five active centers submitted with zero views");
Check(backend.Centers.Values.All(x=>x.Radii==new InterestRadii(32,64)),"explicit readiness/content radii");
interestsRegistry.SetView(Guid.NewGuid(),new(5000,100,5000));coordinator.Sync();
Check(backend.Centers.Count==5&&!backend.Centers.Values.Any(x=>x.Center.X==5000),"camera never becomes simulation center");
interestsRegistry.Update(interestsRegistry.SessionId,interestIds[0],0,new(-123,66,55),true);coordinator.Sync();
Check(backend.Centers[interestIds[0]].Center.X==-123,"native observation moves active center");
interestsRegistry.Update(interestsRegistry.SessionId,interestIds[1],0,new(100,65,0),false);coordinator.Sync();
Check(!backend.Centers.ContainsKey(interestIds[1]),"inactive center released");
interestsRegistry.Remove(interestIds[2]);coordinator.Sync();Check(backend.Centers.Count==3,"removed center released");
int publishedBeforeFailure=backend.Published;backend.FailRemove=true;Reject(()=>coordinator.Release(),"release error visible");Check(backend.Centers.Count==3,"failed release remains tracked");Check(backend.Published==publishedBeforeFailure,"failed batch not published");
backend.FailRemove=false;coordinator.Release();Check(backend.Centers.Count==0,"release retry clears all leases");coordinator.Release();
coordinator.Sync();Check(backend.Centers.Count==3,"coordinator can reattach after release");
Reject(()=>new InterestCoordinator(interestsRegistry,backend,new(0,64)),"zero full-ready radius rejected");
Reject(()=>new InterestCoordinator(interestsRegistry,backend,new(64,32)),"content smaller than full-ready rejected");
Reject(()=>new InterestCoordinator(interestsRegistry,backend,new(float.NaN,64)),"NaN radius rejected");
bool badThread=Task.Run(()=>{try{coordinator.Sync();return false;}catch(InvalidOperationException){return true;}}).GetAwaiter().GetResult();Check(badThread,"background synchronization rejected");
var unboundRegistry=ActorRegistry.Restore(interestsRegistry.Serialize(),interestsRegistry.WorldId);var emptyBackend=new RecordingBackend();new InterestCoordinator(unboundRegistry,emptyBackend,new(32,64)).Sync();Check(emptyBackend.Centers.Count==0,"unreconciled restored bodies not activated");
var partialBackend=new RecordingBackend {FailUpsertAfterWrite=true};var partialCoordinator=new InterestCoordinator(interestsRegistry,partialBackend,new(32,64));
Reject(()=>partialCoordinator.Sync(),"partially applied upsert failure visible");Check(partialBackend.Centers.Count==1&&partialBackend.Published==0,"partial upsert does not publish batch");
partialCoordinator.Release();Check(partialBackend.Centers.Count==0,"failed upsert is still tracked for release");
partialBackend.FailUpsertAfterWrite=false;partialCoordinator.Sync();Check(partialBackend.Centers.Count==3,"retry after partial upsert reconciles centers");
Console.WriteLine($"{checks}/{checks} actor/view contract checks passed; NO native game integration tested");

sealed class RecordingBackend : IInterestBackend {
 public readonly Dictionary<Guid,(Position Center,InterestRadii Radii)> Centers=new();public bool FailRemove,FailUpsertAfterWrite;public int Published;
 public void Publish()=>Published++;
 public void Upsert(Guid id,Position p,InterestRadii r){Centers[id]=(p,r);if(FailUpsertAfterWrite)throw new InvalidOperationException("injected partial write");}
 public void Remove(Guid id){if(FailRemove)throw new InvalidOperationException("injected remove failure");Centers.Remove(id);}
}
